if (operation === 'get#ThreadView' && result.thread) for (const message of Array.from(result.thread.messageList || []))
    if (message.invitation) message.invitation.eventUrl = eventUrl(message.invitation.workEffortId)
handled = true

replySent = false
const answer = String(response || '').toLowerCase()
if (!['accept', 'tentative', 'decline'].includes(answer)) { ec.message.addError(`The answer is accept, tentative or decline, not ${response}`); return }
const out = ec.service.sync().name('org.moqui.impl.EmailClientServices.get#Thread').parameter('emailMessageId', emailMessageId).call()
if (ec.message.hasError()) return
const message = Array.from(out.messageList || []).find((item) => item.emailMessageId === emailMessageId)
const invitation = ec.service.sync().name('ironstone.comms.InboxServices.get#InvitationCard').parameter('attachmentList',
        Array.from(message.attachmentList || [])).call().invitation
if (!invitation) { ec.message.addError(ec.l10n.localize('This message has no invitation')); return }
const partyId = ec.user.userAccount?.partyId
if (!partyId) { ec.message.addError('Answering an invitation needs a user with a party'); return }
workEffortId = invitation.workEffortId
const statusOf = {accept: 'WeptAssigned', tentative: 'WeptTentative', decline: 'WeptDeclined'}
if (workEffortId) {
    const answered = ec.service.sync().name('mantle.work.EventServices.respond#EventInvitation').parameters({workEffortId: workEffortId,
        response: answer, eventUrl: '/qapps/Commons/Calendar/EventDetail?workEffortId=' + encodeURIComponent(workEffortId)}).call()
    if (ec.message.hasError()) return
    statusId = answered.statusId
    replySent = !!answered.replyIcsText
    return
}
// from outside: on the calendar first, then the REPLY from the account it came to
const file = Array.from(message.attachmentList || []).find((item) => item.emailMessageAttachmentId === invitation.emailMessageAttachmentId)
const icsText = ec.resource.getLocationReference(file.attachmentLocation).getText()
const tool = ec.factory.getTool('ICalendar')
const event = Array.from(tool.parse(icsText).events || [])[0]
const calendars = ec.service.sync().name('mantle.work.CalendarServices.get#UserCalendars').call()
if (ec.message.hasError()) return
const organizer = event.organizer || {}
const description = [event.description || '', organizer.email ? ec.l10n.localize('Organizer') + ': ' + (organizer.name ? organizer.name + ' <' + organizer.email + '>' : organizer.email) : '']
        .filter((part) => part).join('\n\n')
const now = ec.user.nowTimestamp
const effort = ec.entity.makeValue('mantle.work.effort.WorkEffort')
effort.setSequencedIdPrimary()
effort.setFields({workEffortTypeEnumId: 'WetEvent', purposeEnumId: 'WepMeeting', statusId: 'WeInPlanning', universalId: event.uid ? String(event.uid) : null,
    workEffortName: event.summary || message.subject || ec.l10n.localize('Invitation'), description: description || null,
    location: event.location || null, estimatedStartDate: event.start != null ? new Date(Number(event.start)) : null,
    estimatedCompletionDate: event.end != null ? new Date(Number(event.end)) : null,
    allDayStart: event.allDay && event.startDate ? event.startDate : null}, true, null, null)
effort.create()
workEffortId = effort.workEffortId
ec.service.sync().name('create#mantle.work.effort.WorkEffortParty').parameters({workEffortId: workEffortId, partyId: partyId,
    roleTypeId: 'Assignee', fromDate: now, statusId: statusOf[answer]}).call()
if (ec.message.hasError()) return
if (calendars.defaultCalendarId) ec.service.sync().name('create#mantle.work.calendar.CalendarWorkEffort').parameters({calendarId: calendars.defaultCalendarId,
    workEffortId: workEffortId, addedDate: now}).call()
if (ec.message.hasError()) { ec.logger.warn(`Invitation ${workEffortId} not put in calendar ${calendars.defaultCalendarId}: ${ec.message.getErrorsString()}`); ec.message.clearErrors() }
statusId = statusOf[answer]
if (!organizer.email || !out.canSend) return
// the REPLY, in a transaction of its own: one that cannot go (an account with no server) is logged, the answer stays
ec.message.pushErrors()
try {
    const reply = ec.service.sync().name('ironstone.comms.InboxServices.send#InvitationReply').parameters({emailMessageId: emailMessageId,
        response: answer, icsLocation: file.attachmentLocation}).requireNewTransaction(true).call()
    if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
    replySent = reply?.sent === true
} catch (err) {
    ec.logger.warn(`The answer to invitation ${invitation.uid} was not sent to ${organizer.email}: ${err && err.message ? err.message : err}`)
} finally { ec.message.clearErrors(); ec.message.popErrors() }

sent = false
const out = ec.service.sync().name('org.moqui.impl.EmailClientServices.get#Thread').parameter('emailMessageId', emailMessageId).call()
if (ec.message.hasError()) return
const message = Array.from(out.messageList || []).find((item) => item.emailMessageId === emailMessageId)
if (!message.canSend) return
const access = ec.service.sync().name('org.moqui.impl.EmailClientServices.get#EmailAccountAccess').parameter('emailAccountId', message.emailAccountId).call()
const account = access.account
const server = account?.emailServerId ? ec.entity.find('moqui.basic.email.EmailServer').condition('emailServerId', account.emailServerId).disableAuthz().one() : null
if (!server || !server.smtpHost) { ec.logger.info(`Email account ${message.emailAccountId} has no outgoing server; no REPLY sent`); return }
const tool = ec.factory.getTool('ICalendar')
const event = Array.from(tool.parse(ec.resource.getLocationReference(icsLocation).getText()).events || [])[0]
const organizer = event.organizer || {}
if (!organizer.email) return
const myAddress = account.emailAddress || ec.user.userAccount?.emailAddress
const partstat = {accept: 'ACCEPTED', tentative: 'TENTATIVE', decline: 'DECLINED'}[response]
const replyEvent = Object.assign({}, event, {attendees: [{email: myAddress, name: ec.user.userAccount?.userFullName || null, partstat: partstat}]})
const ics = tool.write({method: 'REPLY', attendee: myAddress, events: [replyEvent]})
const words = ec.l10n.localize({accept: 'Accepted', tentative: 'Tentative', decline: 'Declined'}[response])
const summary = String(event.summary || message.subject || '')
const draft = ec.service.sync().name('org.moqui.impl.EmailClientServices.save#Draft').parameters({emailAccountId: message.emailAccountId,
    parentEmailMessageId: emailMessageId, toAddresses: organizer.name ? `"${String(organizer.name).replace(/"/g, '')}" <${organizer.email}>` : organizer.email,
    subject: words + ': ' + summary, bodyText: words + ': ' + summary, body: '<p>' + words + ': ' + summary.replace(/[<>&]/g, '') + '</p>'}).call()
if (ec.message.hasError()) return
const location = `dbresource://email/${message.emailAccountId}/${draft.emailMessageId}/reply.ics`
ec.resource.getLocationReference(location).putText(ics)
ec.service.sync().name('org.moqui.impl.EmailClientServices.save#Draft').parameters({emailMessageId: draft.emailMessageId,
    attachmentList: [{attachmentLocation: location, fileName: 'reply.ics', contentType: 'text/calendar; method=REPLY; charset=UTF-8', fileSize: String(ics).length}]}).call()
if (ec.message.hasError()) return
const result = ec.service.sync().name('org.moqui.impl.EmailClientServices.send#Draft').parameter('emailMessageId', draft.emailMessageId).call()
if (ec.message.hasError()) return
sent = result.sent === true || result.statusId === 'ES_READY'

const access = ec.service.sync().name('mantle.marketing.ContactListServices.get#ContactListAccess').parameter('contactListId', contactListId).call()
if (ec.message.hasError()) return
if (!access.exists || !access.isMailbox || !access.canSeeHeader) { ec.message.addError(`Mailbox ${contactListId} not found`); return }
const list = access.contactList || {}
let memberList = [], pendingList = [], memberCount = null
if (access.canReadAll || access.isPublic) {
    ec.message.pushErrors()
    try {
        const members = ec.service.sync().name('mantle.marketing.ContactListServices.find#ContactListParties').parameter('contactListId', contactListId).requireNewTransaction(true).call()
        if (!ec.message.hasError()) {
            memberList = Array.from(members.memberList || []).map((member) => ({partyId: member.partyId, name: member.name, roleTypeId: member.roleTypeId ?? null,
                deliveryEnumId: member.effectiveDeliveryEnumId ?? null, fromDate: member.fromDate ?? null}))
            pendingList = Array.from(members.pendingList || []).map((member) => ({partyId: member.partyId, name: member.name, fromDate: member.fromDate ?? null}))
            memberCount = memberList.length
        }
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
}
mailbox = {contactListId: contactListId, contactListName: list.contactListName ?? contactListId, description: list.description ?? null,
    isPublic: access.isPublic === true, postingEnumId: access.postingEnumId, defaultDeliveryEnumId: list.defaultDeliveryEnumId || 'CldInbox',
    isArchived: access.isArchived === true, isMember: access.isMember === true, membershipStatusId: access.membershipStatusId ?? null,
    memberRoleTypeId: access.memberRoleTypeId ?? null, deliveryEnumId: access.deliveryEnumId ?? null, isOwner: access.isOwner === true,
    canModerate: access.canModerate === true, canReadAll: access.canReadAll === true, canReadOwn: access.canReadOwn === true,
    canPost: access.canPost === true, canJoin: access.canJoin === true, memberCount: memberCount, memberList: memberList, pendingList: pendingList}

service.description:
The palette's Messages and rooms group (design §1.5): the user's mail and internal threads whose text
            matches (find#InboxRows with the search line, so its operators work), and the mailboxes the user may see by name;
            each a row {title, subtitle, icon, url} to the Inbox. moreUrl is the Inbox's search.

actions.script:
rows = []
const term = String(text || '').trim()
if (!term) return
const max = Math.max(1, Math.min(limit || 5, 20))
ec.message.pushErrors()
try {
    const lists = ec.service.sync().name('mantle.marketing.ContactListServices.find#ContactLists').parameters({contactListTypeEnumId: 'MAILBOX',
        searchText: term}).requireNewTransaction(true).call()
    if (!ec.message.hasError()) for (const list of Array.from(lists.contactListList || []).slice(0, 2)) rows.push({title: list.contactListName,
        subtitle: ec.l10n.localize('Mailbox') + (list.description ? ' · ' + list.description : ''), icon: 'sym_o_forum',
        url: '/qapps/Comms/Inbox?mailbox=' + encodeURIComponent(list.contactListId)})
} catch (err) { ec.logger.warn(`Palette mailboxes for ${term} failed: ${err && err.message ? err.message : err}`) }
finally { ec.message.clearErrors(); ec.message.popErrors() }
ec.message.pushErrors()
try {
    const found = ec.service.sync().name('ironstone.comms.InboxServices.find#InboxRows').parameters({view: 'all', searchText: term, pageSize: max}).requireNewTransaction(true).call()
    if (!ec.message.hasError()) for (const row of Array.from(found.threadList || [])) {
        const who = row.store === 'email' ? (row.fromName || row.fromAddress || '') : Array.from(row.participantList || []).map((item) => item.name).join(', ')
        rows.push({title: row.subject || ec.l10n.localize('(no subject)'), subtitle: [row.store === 'email' ? ec.l10n.localize('Mail') : ec.l10n.localize('Message'),
            who, row.snippet].filter((part) => part).join(' · ').substring(0, 160), icon: row.store === 'email' ? 'sym_o_mail' : 'sym_o_chat_bubble',
            url: '/qapps/Comms/Inbox?view=all&q=' + encodeURIComponent(term) + '&thread=' + encodeURIComponent(row.store + ':' + row.threadId)})
    }
} catch (err) { ec.logger.warn(`Palette messages for ${term} failed: ${err && err.message ? err.message : err}`) }
finally { ec.message.clearErrors(); ec.message.popErrors() }
rows = rows.slice(0, max)
moreUrl = '/qapps/Comms/Inbox?q=' + encodeURIComponent(term)

const toMillis = (value) => value == null || value === '' ? null : (typeof value === 'number' ? value : (value instanceof Date ? value.getTime() : Number(String(value))))
const describe = (entityName, field, id) => {
    if (!id) return null
    const row = ec.entity.find(entityName).condition(field, id).useCache(true).disableAuthz().one()
    return row ? (row.description || id) : id
}
const isHtml = (contentType, body) => /html/i.test(contentType || '') || /<(p|div|br|table|html|body|span|a)\b/i.test(String(body || ''))
detail = null
if (!emailMessageId && communicationEventId) {
    const event = ec.entity.find('mantle.party.communication.CommunicationEvent').condition('communicationEventId', communicationEventId).disableAuthz().one()
    if (event == null) { ec.message.addError(`Message ${communicationEventId} not found`); return }
    if (event.emailMessageId) emailMessageId = event.emailMessageId
    else {
        // an internal message the user sees in the Inbox, or another communication event the user may see
        let thread = null
        ec.message.pushErrors()
        try {
            thread = ec.service.sync().name('mantle.party.CommunicationServices.get#InternalThread').parameter('communicationEventId', communicationEventId)
                    .requireNewTransaction(true).call()
            if (ec.message.hasError()) thread = null
        } finally { ec.message.clearErrors(); ec.message.popErrors() }
        if (thread == null) {
            const info = ec.service.sync().name('mantle.party.CommunicationServices.get#RecordLinkInfo').parameters({
                recordEntityName: 'mantle.party.communication.CommunicationEvent', recordId: communicationEventId, checkOnly: true}).call()
            if (ec.message.hasError() || !info.recordVisible) { ec.message.clearErrors(); ec.message.addError(`Message ${communicationEventId} not found`); return }
        }
        const names = {}
        for (const id of [event.fromPartyId, event.toPartyId].filter((id) => id)) {
            const party = ec.entity.find('mantle.party.PartyDetail').condition('partyId', id).disableAuthz().one()
            names[id] = party ? (party.organizationName || [party.firstName, party.lastName].filter((part) => part).join(' ') || id) : id
        }
        const recipients = Array.from(ec.entity.find('mantle.party.communication.CommunicationEventParty').condition('communicationEventId', communicationEventId)
                .condition('roleTypeId', 'in', ['MessageTo', 'MessageCc']).disableAuthz().list())
        for (const row of recipients) if (!names[row.partyId]) {
            const party = ec.entity.find('mantle.party.PartyDetail').condition('partyId', row.partyId).disableAuthz().one()
            names[row.partyId] = party ? (party.organizationName || [party.firstName, party.lastName].filter((part) => part).join(' ') || row.partyId) : row.partyId
        }
        const links = ec.service.sync().name('ironstone.comms.InboxServices.get#CommEventLinks').parameter('communicationEventIdList', [communicationEventId]).call().linkMap || {}
        const files = Array.from(ec.entity.find('mantle.party.communication.CommunicationEventContent').condition('communicationEventId', communicationEventId)
                .orderBy('sequenceNum').disableAuthz().list())
        detail = {kind: 'internal', communicationEventId: communicationEventId, subject: event.subject || '', fromText: names[event.fromPartyId] || '',
            toText: [event.toPartyId].concat(recipients.filter((row) => row.roleTypeId === 'MessageTo').map((row) => row.partyId)).filter((id, index, list) => id && list.indexOf(id) === index)
                .map((id) => names[id]).join(', '), ccText: recipients.filter((row) => row.roleTypeId === 'MessageCc').map((row) => names[row.partyId]).join(', '),
            bccText: '', dateMillis: toMillis(event.entryDate), messageId: null, accountText: ec.l10n.localize('Internal'), folderText: null,
            statusText: describe('moqui.basic.StatusItem', 'statusId', event.statusId), typeText: describe('mantle.party.communication.CommunicationEventType',
                'communicationEventTypeId', event.communicationEventTypeId), templateText: null, serverText: null,
            html: isHtml(event.contentType, event.body) ? event.body : null, text: isHtml(event.contentType, event.body) ? null : (event.body || ''),
            headersText: null, attachmentList: files.map((file) => ({id: file.communicationEventContentId, store: 'internal',
                name: file.description || String(file.contentLocation || '').split('/').pop()})),
            commEventList: [], linkList: links[communicationEventId] || [], threadKey: thread ? 'internal:' + (thread.rootCommEventId || communicationEventId) : null,
            emailMessageId: null, canResend: false}
        return
    }
}
if (!emailMessageId) { ec.message.addError('An emailMessageId or communicationEventId is required'); return }
const row = ec.entity.find('moqui.basic.email.EmailMessage').condition('emailMessageId', emailMessageId).disableAuthz().one()
if (row == null) { ec.message.addError(`Email message ${emailMessageId} not found`); return }
let message = null
let canSend = false
if (row.emailAccountId) {
    const out = ec.service.sync().name('org.moqui.impl.EmailClientServices.get#Thread').parameters({emailMessageId: emailMessageId, includeHeaders: true}).call()
    if (ec.message.hasError()) return
    message = Array.from(out.messageList || []).find((item) => item.emailMessageId === emailMessageId)
    canSend = message.canSend === true
} else {
    // mail the system sent: for administrators
    if (!ec.user.isInGroup('ADMIN')) { ec.message.addError(`Email message ${emailMessageId} not found`); return }
    message = row.getMap()
    message.attachmentList = []
}
const account = row.emailAccountId ? ec.entity.find('moqui.basic.email.EmailAccount').condition('emailAccountId', row.emailAccountId).one() : null
const folder = row.emailFolderId ? ec.entity.find('moqui.basic.email.EmailFolder').condition('emailFolderId', row.emailFolderId).one() : null
const template = row.emailTemplateId ? ec.entity.find('moqui.basic.email.EmailTemplate').condition('emailTemplateId', row.emailTemplateId).disableAuthz().one() : null
const server = row.emailServerId ? ec.entity.find('moqui.basic.email.EmailServer').condition('emailServerId', row.emailServerId).disableAuthz().one() : null
const events = Array.from(ec.entity.find('mantle.party.communication.CommunicationEvent').condition('emailMessageId', emailMessageId).disableAuthz().list())
const links = ec.service.sync().name('ironstone.comms.InboxServices.get#CommEventLinks').parameter('communicationEventIdList', events.map((event) => event.communicationEventId)).call().linkMap || {}
const linkList = []
for (const event of events) for (const link of (links[event.communicationEventId] || []))
    if (!linkList.some((other) => other.recordEntityName === link.recordEntityName && other.recordId === link.recordId)) linkList.push(link)
const body = message.body
const html = isHtml(message.contentType, body) ? body : null
detail = {kind: 'email', emailMessageId: emailMessageId, communicationEventId: events.length ? events[0].communicationEventId : null, subject: message.subject || '',
    fromText: message.fromName ? `${message.fromName} <${message.fromAddress}>` : (message.fromAddress || ''), toText: message.toAddresses || '',
    ccText: message.ccAddresses || '', bccText: message.bccAddresses || '', dateMillis: toMillis(message.messageDate || message.sentDate || message.receivedDate),
    messageId: message.messageId || null, accountText: account ? (account.accountName ? `${account.accountName} <${account.emailAddress}>` : account.emailAddress) : null,
    folderText: folder ? (folder.folderName || folder.folderPath) : null, statusId: row.statusId, statusText: describe('moqui.basic.StatusItem', 'statusId', row.statusId),
    typeText: describe('moqui.basic.Enumeration', 'enumId', row.emailTypeEnumId), templateText: template ? (template.description || template.emailTemplateId) : null,
    serverText: server ? (server.smtpHost || server.emailServerId) : null, html: html, text: message.bodyText || (html ? null : (body || '')),
    headersText: message.headersString || null, sendError: row.sendError || null,
    attachmentList: Array.from(message.attachmentList || []).map((file) => ({id: file.emailMessageAttachmentId, store: 'email', name: file.fileName || 'attachment',
        size: file.fileSize ?? null})),
    commEventList: events.map((event) => ({communicationEventId: event.communicationEventId, typeText: describe('mantle.party.communication.CommunicationEventType',
        'communicationEventTypeId', event.communicationEventTypeId), statusText: describe('moqui.basic.StatusItem', 'statusId', event.statusId), subject: event.subject})),
    linkList: linkList, threadKey: row.emailAccountId ? 'email:' + (row.rootEmailMessageId || emailMessageId) : null,
    canResend: (!row.emailAccountId && ec.user.isInGroup('ADMIN')) || (row.statusId === 'ES_BOUNCED' && canSend),
    isSystemMail: !row.emailAccountId}

const L = (text) => ec.l10n.localize(text)
savedList = []
failedList = []
const safe = (name) => String(name || 'attachment').replace(/[\/\\?#%:*"<>|]/g, '_').substring(0, 120)
const files = []
if (id) {
    const one = ec.service.sync().name('ironstone.comms.InboxServices.get#MessageAttachment').parameters({store: store || '', id: id}).call()
    if (ec.message.hasError()) return
    files.push({name: one.fileName || 'attachment', location: one.location})
} else if (emailMessageId) {
    ec.message.pushErrors()
    let readable = false
    try {
        const out = ec.service.sync().name('org.moqui.impl.EmailClientServices.get#Thread').parameter('emailMessageId', emailMessageId).requireNewTransaction(true).call()
        readable = !ec.message.hasError() && Array.from(out.messageList || []).some((message) => message.emailMessageId === emailMessageId)
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
    if (!readable) { ec.message.addError(L('Attachment not found') + ': ' + emailMessageId); return }
    for (const file of ec.entity.find('moqui.basic.email.EmailMessageAttachment').condition('emailMessageId', emailMessageId).list()) {
        if (file.attachmentLocation) files.push({name: file.fileName || 'attachment', location: file.attachmentLocation})
    }
} else if (communicationEventId) {
    ec.message.pushErrors()
    let readable = false
    try {
        const out = ec.service.sync().name('mantle.party.CommunicationServices.get#InternalThread').parameter('communicationEventId', communicationEventId).requireNewTransaction(true).call()
        readable = !ec.message.hasError() && Array.from(out.messageList || []).some((message) => message.communicationEventId === communicationEventId)
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
    if (!readable) { ec.message.addError(L('Attachment not found') + ': ' + communicationEventId); return }
    for (const file of ec.entity.find('mantle.party.communication.CommunicationEventContent').condition('communicationEventId', communicationEventId).disableAuthz().list()) {
        if (file.contentLocation) files.push({name: file.description || String(file.contentLocation).split('/').pop() || 'attachment', location: file.contentLocation})
    }
} else { ec.message.addError(L('Name the file to save')); return }
if (!files.length) { ec.message.addError(L('This message has no files')); return }
for (const file of files) {
    const label = file.name
    ec.message.pushErrors()
    try {
        const stream = ec.resource.getLocationReference(file.location).openStream()
        if (!stream) throw new Error(L('Attachment not found') + ': ' + label)
        try {
            const out = ec.service.sync().name('org.moqui.impl.FileServices.upload#Resource').parameters({driveId: driveId, path: path || '',
                file: stream, relativePathList: [safe(label)], conflictPolicy: 'keepBoth',
                versionNote: L('Saved from a message')}).call()
            if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
            const row = Array.from(out.uploadedList || [])[0]
            if (!row || row.outcome === 'failed') throw new Error((row && row.error) || L('Not saved'))
            savedList.push({name: row.name, path: row.path, outcome: row.outcome})
        } finally { if (stream.close) stream.close() }
    } catch (err) {
        const why = err && err.message ? err.message : String(err)
        ec.logger.warn(`Save to Files: ${label} not saved: ${why}`)
        failedList.push({name: label, error: why})
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
}
if (!savedList.length && failedList.length) ec.message.addError(failedList[0].error)
